package rolecase

import (
	"os"
	"strings"
	"testing"
)

func TestIsAllowed(t *testing.T) {
	data, _ := os.ReadFile("allowed_roles.txt")
	for _, role := range strings.Split(strings.TrimSpace(string(data)), ",") {
		role = strings.TrimSpace(role)
		if !IsAllowed(role) {
			t.Fatalf("IsAllowed(%q) should be true", role)
		}
	}
	if IsAllowed("not_a_real_role") {
		t.Fatal("IsAllowed should reject an unknown role")
	}
}

