package rolecase

import (
	"os"
	"strings"
)

func IsAllowed(role string) bool {
	data, err := os.ReadFile("allowed_roles.txt")
	if err != nil {
		return false
	}
	for _, r := range strings.Split(strings.TrimSpace(string(data)), ",") {
		if strings.TrimSpace(r) == role {
			return true
		}
	}
	return false
}

